def apply_discount(prices, rate):
    """Return the prices after applying a discount rate."""
    if not prices:
        return []
    if not 0 < rate < 1:
        raise ValueError("rate must be between 0 and 1")
    result = []
    for price in prices:
        result.append(round(price * (1 - rate), 2))
    return result
```
